      {supplierOpen?<View style={styles.supplierProjects}><TouchableOpacity style={styles.secondary} onPress={()=>editSupplier(supplier.id)} accessibilityRole="button"><Text style={styles.secondaryText}>Edit supplier information</Text></TouchableOpacity>{editingSupplierId===supplier.id&&showSupplier?<View style={styles.nested}><Field label="Supplier name *" value={supplierName} onChangeText={setSupplierName}/><Field label="Phone" value={supplierPhone} onChangeText={setSupplierPhone}/><Field label="Email" value={supplierEmail} onChangeText={setSupplierEmail}/><Field label="Address" value={supplierAddress} onChangeText={setSupplierAddress}/><Field label="Tax / VAT number" value={supplierTax} onChangeText={setSupplierTax}/><Field label="Notes" value={supplierNotes} onChangeText={setSupplierNotes} multiline/><TouchableOpacity style={styles.darkButton} disabled={busy} onPress={()=>void saveSupplier()} accessibilityRole="button"><Text style={styles.darkButtonText}>Save supplier changes</Text></TouchableOpacity><TouchableOpacity style={styles.clearWrap} onPress={clearSupplierForm} accessibilityRole="button"><Text style={styles.clear}>Cancel editing</Text></TouchableOpacity></View>:null}{supplier.projectGroups.map(project=>{const projectKey=`${supplier.id}:${project.id??'unlinked'}`;const projectOpen=openProjects.has(projectKey);const tripInfo=computeTripInfo(project.purchases);const visibleCount=visibleCounts[projectKey]??HISTORY_PAGE;const visible=project.purchases.slice(0,visibleCount);const remaining=project.purchases.length-visible.length;return <View key={projectKey} style={styles.projectGroup}><TouchableOpacity activeOpacity={.72} style={[styles.projectHeader,project.id===null&&styles.unlinkedProjectHeader]} onPress={()=>toggleProject(projectKey)} accessibilityRole="button" accessibilityState={{expanded:projectOpen}}><View style={styles.groupCopy}><Text style={styles.projectEyebrow}>{project.id===null?'GENERAL PURCHASES':'LINKED PROJECT'}</Text><Text style={styles.projectName}>{project.name}</Text><Text style={styles.projectMeta}>{project.purchases.length} purchase{project.purchases.length===1?'':'s'}</Text></View><RotatingMark open={projectOpen} color={colors.navy} reducedMotion={reducedMotion} size={22}/></TouchableOpacity>{projectOpen?<View style={styles.projectPurchases}>{visible.map((purchase,index)=>{const trip=tripInfo.get(purchase.id)??null;const previous=visible[index-1];const previousTrip=previous?tripInfo.get(previous.id):null;const connectAbove=Boolean(trip&&previousTrip&&trip.clusterKey===previousTrip.clusterKey);return <View key={purchase.id}>{connectAbove?<View style={styles.tripRail}/>:null}<SuppliedMaterialRow purchase={purchase} trip={trip} onPress={()=>openPurchase(purchase)}/></View>;})}{remaining>0?<TouchableOpacity style={styles.secondary} onPress={()=>showMore(projectKey)} accessibilityRole="button"><Text style={styles.secondaryText}>Show {Math.min(remaining,HISTORY_PAGE)} More ({remaining} remaining)</Text></TouchableOpacity>:null}</View>:null}</View>})}</View>:null}
