function toggleSet(current:Set<string>,key:string){const next=new Set(current);if(next.has(key))next.delete(key);else next.add(key);return next;}
function RotatingMark({open,color,reducedMotion,size=25}:{open:boolean;color:string;reducedMotion:boolean;size?:number}){
  const rotate=useState(()=>new Animated.Value(open?1:0))[0];
  useEffect(()=>{Animated.timing(rotate,{toValue:open?1:0,duration:reducedMotion?0:200,useNativeDriver:true}).start();},[open,reducedMotion,rotate]);
  return <Animated.Text style={[styles.rotatingMark,{color,fontSize:size,transform:[{rotate:rotate.interpolate({inputRange:[0,1],outputRange:['0deg','45deg']})}]}]}>+</Animated.Text>;
}
function SuppliedMaterialRow({purchase,trip,onPress}:{purchase:QuarryPurchase;trip:TripInfo|null;onPress:()=>void}){
  const cancelled=purchase.status==='Cancelled';const reactivated=!cancelled&&purchase.cancelledAt!=null;
  const accent=cancelled?colors.danger:reactivated?colors.warning:colors.brand;
  const delivery=purchase.deliveryMethod==='supplier'?`Supplier Delivering${purchase.truckPlate?` · ${purchase.truckPlate}`:''}`:`${purchase.driverName} · ${purchase.truckPlate}`;
  return <TouchableOpacity style={[styles.materialRow,{borderLeftColor:accent}]} onPress={onPress} accessibilityRole="button">
    <View style={styles.materialTop}><View style={styles.flex}><Text style={styles.materialName}>{purchase.itemName}</Text><Text style={styles.materialCategory}>{purchase.categoryName}</Text></View>{trip?<View style={styles.tripBadge}><Text style={styles.tripBadgeText}>Trip {trip.index} of {trip.total}</Text></View>:null}</View>
    <Text style={styles.quantityValue}>{purchase.quantityCubicMetres}{' '}<Text style={styles.quantityUnit}>{purchase.unitSymbol}</Text></Text>
    <View style={styles.ledgerDivider}/>
    <View style={styles.detailBlocks}>
      <View style={styles.detailBlock}><Text style={styles.detailHeading}>OPERATIONAL</Text><Text style={styles.detailLine}>{new Date(purchase.confirmedAt).toLocaleString()}</Text><Text style={styles.detailLine}>{delivery}</Text><Text style={styles.detailLine}>{purchase.priceBasis==='whole'?'As a Whole':'Per Unit'}</Text></View>
      <View style={styles.detailBlock}><Text style={styles.detailHeading}>FINANCIAL</Text>{purchase.finalTotalUsd!=null?<><Text style={styles.detailLineStrong}>${purchase.finalTotalUsd.toFixed(2)}</Text><Text style={styles.detailLine}>{purchase.vatInclusive?'VAT included':'VAT added'} · {purchase.vatRatePercent}%</Text></>:<Text style={styles.unpricedTag}>Unpriced</Text>}</View>
    </View>
    <View style={styles.materialFooter}>{cancelled?<View style={[styles.statusBadge,styles.statusBadgeDanger]}><Text style={styles.statusBadgeText}>Cancelled</Text></View>:null}{reactivated?<View style={[styles.statusBadge,styles.statusBadgeWarning]}><Text style={styles.statusBadgeText}>Reactivated · corrected and restored for review</Text></View>:null}<Text style={styles.referenceText}>Ref {purchase.purchaseNumber}{purchase.supplierTicketNumber?` · Ticket #${purchase.supplierTicketNumber}`:''}</Text></View>
    {purchase.notes?<Text style={styles.materialNotes}>{purchase.notes}</Text>:null}
    {cancelled?<Text style={styles.cancelledReason}>Reason: {purchase.cancellationReason}</Text>:null}
  </TouchableOpacity>;
}
function PriceVatControls({value,companyVat,onChange}:{value:Pick<QuarryPurchaseDraft,'priceBasis'|'unitPriceUsd'|'vatMode'|'customVatRatePercent'|'vatInclusive'>;companyVat:number;onChange:(changes:Partial<QuarryPurchaseDraft>)=>void}){return <><View style={styles.choiceRow}><DeliveryChoice label="Per Unit · Quantity × Price" selected={value.priceBasis==='per_unit'} onPress={()=>onChange({priceBasis:'per_unit'})}/><DeliveryChoice label="As a Whole · Use Price once" selected={value.priceBasis==='whole'} onPress={()=>onChange({priceBasis:'whole'})}/></View><Field label="Price (USD, optional)" value={value.unitPriceUsd} onChangeText={(v)=>onChange({unitPriceUsd:v})} keyboardType="decimal-pad" placeholder="Leave blank for Unpriced"/><View style={styles.choiceRow}><DeliveryChoice label="VAT Excluded · Add VAT" selected={!value.vatInclusive} onPress={()=>onChange({vatInclusive:false})}/><DeliveryChoice label="VAT Included · VAT is in Price" selected={value.vatInclusive} onPress={()=>onChange({vatInclusive:true})}/></View><View style={styles.choiceRow}><DeliveryChoice label={`Company VAT · ${companyVat}%`} selected={value.vatMode==='company'} onPress={()=>onChange({vatMode:'company'})}/><DeliveryChoice label="No VAT · 0%" selected={value.vatMode==='none'} onPress={()=>onChange({vatMode:'none'})}/><DeliveryChoice label="Custom VAT" selected={value.vatMode==='custom'} onPress={()=>onChange({vatMode:'custom'})}/></View>{value.vatMode==='custom'?<Field label="Custom VAT rate (%) *" value={value.customVatRatePercent} onChangeText={(v)=>onChange({customVatRatePercent:v})} keyboardType="decimal-pad"/>:null}</>}
function DeliveryChoice({label,selected,onPress}:{label:string;selected:boolean;onPress:()=>void}){return <TouchableOpacity style={[styles.deliveryChoice,selected&&styles.deliveryChoiceSelected]} onPress={onPress} accessibilityRole="button" accessibilityState={{selected}}><Text style={[styles.deliveryChoiceText,selected&&styles.deliveryChoiceTextSelected]}>{label}</Text></TouchableOpacity>}
function Header({title,onBack}:{title:string;onBack:()=>void}){return <View style={styles.header}><TouchableOpacity onPress={onBack} style={styles.back} accessibilityRole="button"><Text style={styles.backText}>Back</Text></TouchableOpacity><View><Text style={styles.eyebrow}>INCOMING MATERIAL</Text><Text style={styles.title}>{title}</Text></View></View>}
function Card({title,hint,children}:{title:string;hint?:string;children:React.ReactNode}){return <View style={styles.card}><Text style={styles.cardTitle}>{title}</Text>{hint?<Text style={styles.helper}>{hint}</Text>:null}{children}</View>}
function Field({label,...props}:{label:string;value:string;onChangeText:(v:string)=>void;placeholder?:string;multiline?:boolean;keyboardType?:'default'|'decimal-pad'|'number-pad'}){return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput style={[styles.input,props.multiline&&styles.multiline]} placeholderTextColor="#89939B" {...props}/></View>}
function Total({label,value,strong}:{label:string;value:number;strong?:boolean}){return <View style={styles.row}><Text style={[styles.helper,strong&&styles.strong]}>{label}</Text><Text style={[styles.money,strong&&styles.strong]}>${value.toFixed(2)}</Text></View>}
